function renderCoopDecks(){let box=$('coopDeckRows');box.innerHTML='';for(let r=0;r<coopVisibleRows;r++){let row=document.createElement('section');row.className='coop-deck-row';row.innerHTML=`<div class="coop-deck-head"><h3>デッキ${r+1}</h3><div class="coop-deck-actions">${r===0?'<button class="mini-reset coop-autofill" type="button">デッキ1のみ自動入力</button>':''}<button class="mini-reset coop-copy" type="button">${coopClipboard===r?'コピー中':'コピー'}</button>${coopClipboard!==null&&coopClipboard!==r?'<button class="mini-reset coop-paste" type="button">ペースト</button>':''}${r>0?'<button class="mini-reset danger coop-delete" type="button">デッキ削除</button>':''}</div></div><div class="coop-deck-slots"></div><div class="coop-row-result" id="coopRowResult${r}"></div>`;let slots=row.querySelector('.coop-deck-slots');for(let s=0;s<5;s++){let c=coopDecks[r][s],card=document.createElement('article');card.className='coop-deck-slot';card.innerHTML=`<div class="coop-slot-main"><button type="button" class="coop-character coop-character-image-only" aria-label="${esc(c?.name||'味方キャラを選択')}" title="${esc(c?.name||'味方キャラを選択')}">${coopImage(c)}</button><button type="button" class="mini-reset coop-skill-check">スキル確認</button></div><div class="coop-skill-detail" hidden></div>`;card.querySelector('.coop-character').onclick=()=>openCoopPicker('deck',r*5+s);card.querySelector('.coop-skill-check').onclick=()=>toggleCoopSkillDetail(r,s,card.querySelector('.coop-skill-detail'));slots.append(card)}row.querySelector('.coop-autofill')?.addEventListener('click',recommendCoopDecks);row.querySelector('.coop-delete')?.addEventListener('click',()=>deleteCoopDeck(r));row.querySelector('.coop-copy').onclick=()=>{coopClipboard=r;renderCoopDecks()};row.querySelector('.coop-paste')?.addEventListener('click',()=>{coopDecks[r]=coopDecks[coopClipboard].slice();syncCoopVisibleRows();renderCoopDecks();saveCoopState()});box.append(row)}calculateCoop()}
