function effectDuration(e){let n=Number(e?.duration);return Number.isFinite(n)&&n>0?Math.floor(n):1}
function shortenValue(e){let v=raw(e?.value??e?.amount??e?.['効果量']);return Number.isFinite(v)?Math.max(0,Math.floor(v)):0}
