function coopAppliedSkillLabel(x,recipient,slot){if(!coopRecipientMatches(x,recipient))return null;let e=x.effect,n=en(e),v=amt(e),remaining=Math.max(1,x.remaining??(x.source+effectDuration(e)-slot)),effect='';if(n==='攻撃力アップ'&&Number.isFinite(v))effect=`攻撃力${fmt(v)}%増加`;else if(n==='連撃')effect=`${Math.max(1,Math.floor(raw(e.value??e.amount)))}回連撃`;else if(n==='全体攻撃')effect='全体攻撃';else return null;return {owner:x.owner?.name||'不明',duration:`${remaining}ターン`,effect,ally:coopAllyCondition(e),enemy:coopEnemyCondition(e)}}
function coopSkillMergeKey(x){return [x.duration,x.effect,x.ally,x.enemy].join('|')}
function toggleCoopSkillDetail(row,slot,box){let shouldOpen=box.hidden;document.querySelectorAll('.coop-skill-detail').forEach(x=>x.hidden=true);if(!shouldOpen)return;let recipient=coopDecks[row][slot];if(!recipient){box.innerHTML='<section><p>キャラを選択してください</p></section>';box.hidden=false;return}let skill=coopAllDeckSkills(slot,recipient,'',row),rawItems=skill.active.map(x=>{let item=coopAppliedSkillLabel(x,recipient,slot);return item?{...item,deckRow:x.deckRow}:null}).filter(Boolean),merged=new Map();for(let item of rawItems){let key=coopSkillMergeKey(item),entry=merged.get(key);if(!entry){entry={...item,count:0,sources:[]};merged.set(key,entry)}entry.count++;entry.sources.push(`デッキ${item.deckRow+1}/${item.owner}`)}let items=[...merged.values()],sameCount=rawItems.filter(x=>x.deckRow===row).length,otherCount=rawItems.length-sameCount,html=items.map(x=>`<article class="coop-applied-skill"><b>${esc(x.duration)}の間、${esc(x.effect)}${x.count>1?` ×${x.count}件`:''}</b><small>発動元: ${esc(x.sources.join('、'))}</small><small>適用条件: ${esc(x.ally)} / ${esc(x.enemy)}</small></article>`).join('');box.innerHTML=`<section><b>${esc(recipient.name||`${slot+1}枠目のキャラ`)}</b><small>累積短縮: ${skill.shorten} / 同じデッキ由来: ${sameCount}件 / 他デッキ由来: ${otherCount}件</small><div>${html||'<p>適用中のスキルなし</p>'}</div></section>`;box.hidden=false}
function coopAttackProfile(c,enemy,skill){if(!c||!enemy?.hp)return{perHit:0,hits:0};let d=c.details||{},power=Number(d.limitPower??d.power??0),attr=norm(d.attribute),atk=1,hits=1,all=1;for(let x of skill.active){let e=x.effect;if(!coopEffectApplies(x,c,enemy))continue;let n=en(e),v=amt(e);if(n==='攻撃力アップ'&&Number.isFinite(v))atk*=1+v/100;else if(n==='連撃')hits+=Math.max(1,Math.floor(raw(e.value??e.amount)))-1;else if(n==='全体攻撃')all=5}return{perHit:Math.floor(power*COOP_DAMAGE_BASE*(MATCH[attr]?.[enemy.attribute]??1)*atk*all),hits}}
function coopDamage(c,enemy,skill){let attack=coopAttackProfile(c,enemy,skill);return attack.perHit*attack.hits}
function coopAttackOutcomes(hps,hitDamages,hits,initialTarget){let out=[],seen=new Set();function walk(left,current,fixed){if(left<=0||!current.some(h=>h>0)){let key=current.join(',');if(!seen.has(key)){seen.add(key);out.push(current)}return}let living=[];for(let pos=0;pos<3;pos++)if(current[pos]>0)living.push(pos);let targets=fixed!=null&&current[fixed]>0?[fixed]:living;for(let target of targets){let next=current.slice();next[target]=Math.max(0,next[target]-hitDamages[target]);walk(left-1,next,fixed!=null&&next[fixed]>0?fixed:null)}}walk(hits,hps.slice(),initialTarget);return out}
function permutations(a){if(a.length<2)return[a.slice()];let out=[];a.forEach((v,i)=>permutations(a.slice(0,i).concat(a.slice(i+1))).forEach(p=>out.push([v,...p])));return out}
